#!/usr/bin/env python3
import os
import requests
from flask import Flask, jsonify

try:
    from bitcoinlib.encoding import hex_to_bytes
    HAVE_BITCOINLIB = True
except Exception:
    HAVE_BITCOINLIB = False

app = Flask(__name__)

CONF_PATHS = [
    os.environ.get("BITCOIN_CONF", ""),
    os.path.expanduser("~/.bitcoin/bitcoin.conf"),
    "/etc/bitcoin/bitcoin.conf",
    "/app/bitcoin.conf",
]


def _parse_conf(path):
    cfg = {}
    try:
        with open(path) as fh:
            for line in fh:
                line = line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                k, v = line.split("=", 1)
                k = k.strip().lower()
                v = v.strip().strip('"').strip("'")
                if k in ("rpcuser", "rpcpassword", "rpcport"):
                    cfg[k] = v
    except OSError:
        pass
    return cfg


def get_rpc_config():
    conf = {}
    for p in CONF_PATHS:
        if p and os.path.exists(p):
            conf = _parse_conf(p)
            break
    host = os.environ.get("BITCOIN_RPC_HOST", "127.0.0.1")
    port = os.environ.get("BITCOIN_RPC_PORT", conf.get("rpcport", "8332"))
    user = os.environ.get("BITCOIN_RPC_USER", conf.get("rpcuser", ""))
    pwd = os.environ.get("BITCOIN_RPC_PASS", conf.get("rpcpassword", ""))
    try:
        port = int(port)
    except ValueError:
        port = 8332
    return {"host": host, "port": port, "user": user, "password": pwd, "timeout": float(os.environ.get("BITCOIN_RPC_TIMEOUT", "10"))}


class RpcError(Exception):
    def __init__(self, msg, connection=False):
        super().__init__(msg)
        self.connection = connection


class BitcoinRPC:
    def __init__(self, cfg=None):
        self.cfg = cfg or get_rpc_config()

    def _url(self):
        return "http://%s:%d/" % (self.cfg["host"], self.cfg["port"])

    def call(self, method, params=None):
        payload = {"jsonrpc": "1.0", "id": "svc", "method": method, "params": params or []}
        try:
            resp = requests.post(self._url(), json=payload, auth=(self.cfg["user"], self.cfg["password"]) or None, timeout=self.cfg["timeout"])
        except requests.exceptions.RequestException as exc:
            raise RpcError("Unable to connect to Bitcoin node: %s" % exc, connection=True)
        try:
            data = resp.json()
        except ValueError:
            raise RpcError("Invalid response from Bitcoin node", connection=True)
        if isinstance(data, dict) and data.get("error"):
            raise RpcError(data["error"].get("message", "RPC error"))
        return data.get("result")


def _rpc():
    return BitcoinRPC()


def _validate_hex(value, length=None):
    if not isinstance(value, str):
        return False
    v = value.strip()
    if length is not None and len(v) != length:
        return False
    try:
        if HAVE_BITCOINLIB:
            hex_to_bytes(v)
        else:
            bytes.fromhex(v)
        return True
    except Exception:
        return False


def _not_connected():
    return jsonify({"status": "Not connected to the Bitcoin network"}), 503


@app.route("/")
def index():
    return jsonify({"service": "bitcoin-service", "endpoints": ["/block/<hash>", "/transaction/<txid>", "/status"]})


@app.route("/status")
def status():
    try:
        info = _rpc().call("getblockchaininfo")
        return jsonify({"status": "online", "blocks": info.get("blocks"), "chain": info.get("chain")})
    except RpcError:
        return _not_connected()


@app.route("/block/<block_hash>")
def get_block(block_hash):
    if not _validate_hex(block_hash, 64):
        return jsonify({"error": "Invalid block hash"}), 404
    try:
        block = _rpc().call("getblock", [block_hash, 1])
    except RpcError as exc:
        if exc.connection:
            return _not_connected()
        return jsonify({"error": "Block not found"}), 404
    return jsonify({"hash": block.get("hash"), "height": block.get("height"), "merkleroot": block.get("merkleroot"), "time": block.get("time"), "nonce": block.get("nonce"), "tx": block.get("tx", [])})


@app.route("/transaction/<txid>")
def get_transaction(txid):
    if not _validate_hex(txid, 64):
        return jsonify({"error": "Invalid transaction id"}), 404
    try:
        tx = _rpc().call("getrawtransaction", [txid, 1])
    except RpcError as exc:
        if exc.connection:
            return _not_connected()
        return jsonify({"error": "Transaction not found"}), 404
    vin = []
    for vi in tx.get("vin", []):
        item = {"sequence": vi.get("sequence")}
        if "coinbase" in vi:
            item["coinbase"] = vi["coinbase"]
        if "txid" in vi:
            item["txid"] = vi["txid"]
            item["vout"] = vi.get("vout")
        vin.append(item)
    vout = []
    for v in tx.get("vout", []):
        spk = v.get("scriptPubKey", {})
        vout.append({"value": v.get("value"), "n": v.get("n"), "scriptPubKey": {"asm": spk.get("asm"), "hex": spk.get("hex"), "type": spk.get("type")}})
    return jsonify({"txid": tx.get("txid"), "blockhash": tx.get("blockhash"), "vin": vin, "vout": vout})


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000, threaded=True)
